    return size


class Cover:
    def __init__(self, attributes):
        self.__dict__.update(dict(attributes))

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        cover_id = int(cover_id)
        if not 0 <= cover_id < 10**10:
            raise ValueError('cover ID must fit in ten digits')
        digits = f'{cover_id:010d}'
        return digits[:4], digits[4:6]

    @staticmethod
    def get_cover_url(cover_id, size='', ext='jpg', protocol='https'):
        size = _size(size)
        if protocol not in ('http', 'https'):
            raise ValueError('protocol must be http or https')
        ext = ext.lstrip('.')
        if not re.fullmatch(r'[a-zA-Z0-9]+', ext):
            raise ValueError('invalid extension')
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        prefix = f'{size}_' if size else ''
        suffix = f'-{size.upper()}' if size else ''
        digits = f'{int(cover_id):010d}'
        return (f'{protocol}://archive.org/download/{prefix}covers_{item_id}/'
                f'{prefix}covers_{item_id}_{batch_id}.zip/{digits}{suffix}.{ext}')

    def files(self):
        for size in SIZES:
            field = f'filename_{size}' if size else 'filename'
            filename = getattr(self, field, None)
            if filename:
                yield size, field, os.path.join(config.data_root, 'localdisk', filename)

    def valid_files(self):
        files = list(self.files())
        return len(files) == len(SIZES) and all(os.path.isfile(p) for _, _, p in files)

    def delete_files(self):
        for _, _, path in self.files():
            os.remove(path)


class Batch:
    def __init__(self, item_id, batch_id, size=''):
        self.item_id, self.batch_id = item_id, batch_id
        self.size = _size(size) if size else ''

    def _norm_ids(self):
        item_id, batch_id = int(self.item_id), int(self.batch_id)
        if not 0 <= item_id <= 9999 or not 0 <= batch_id <= 99:
            raise ValueError('invalid item or batch ID')
        return f'{item_id:04d}', f'{batch_id:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls(item_id, batch_id)._norm_ids()
        size = _size(size)
        prefix = f'{size}_' if size else ''
        return os.path.join('items', f'{prefix}covers_{item_id}',
                            f'{prefix}covers_{item_id}_{batch_id}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    @contextlib.contextmanager
    def lock(self):
        item_id, batch_id = self._norm_ids()
        path = os.path.join(config.data_root, 'items', '.locks', f'{item_id}_{batch_id}.lock')
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'a+b') as lockfile:
            fcntl.flock(lockfile, fcntl.LOCK_EX)
            try:
                yield
            finally:
                fcntl.flock(lockfile, fcntl.LOCK_UN)

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        \"\"\"Upload staged zip files and finalize only after all four are present remotely.\"\"\"
        uploader = uploader or Uploader()
        with self.lock():
            item_id, batch_id = self._norm_ids()
            sizes = (self.size,) if self.size else SIZES
            for size in sizes:
                path = self.get_abspath(item_id, batch_id, size)
                if not os.path.isfile(path):
                    continue
                prefix = f'{size}_' if size else ''
                item = f'{prefix}covers_{item_id}'
                if upload and not test and not uploader.is_uploaded(item, os.path.basename(path)):
                    uploader.upload(item, [path])
