                path = self.get_abspath(item_id, batch_id, size)
                if os.path.exists(path):
                    os.remove(path)


class ZipManager:
    def __init__(self):
        self.zips = {}

    def add_file(self, name, filepath, mtime):
        match = re.fullmatch(r'(\\d{10})(?:-([SML]))?\\.([a-zA-Z0-9]+)', name)
        if not match:
            raise ValueError(f'invalid cover filename: {name}')
        cover_id, suffix, _ = match.groups()
        size = suffix.lower() if suffix else ''
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zips:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            z = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)
            self.zips[path] = (z, set(z.namelist()))
        z, names = self.zips[path]
        if name not in names:
            info = zipfile.ZipInfo(name, time.localtime(mtime)[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source:
                z.writestr(info, source.read())
            names.add(name)
        return f'{Batch.get_relpath(item_id, batch_id, size)}/{name}'

    def close(self):
        for z, _ in self.zips.values():
            z.close()
        self.zips.clear()


def get_zipfile(name):
    match = re.fullmatch(r'(\\d{10})(?:-([SML]))?\\.[a-zA-Z0-9]+', name)
    if not match:
        raise ValueError(f'invalid cover filename: {name}')
    item_id, batch_id = Cover.id_to_item_and_batch_id(match.group(1))
    path = Batch.get_abspath(item_id, batch_id, (match.group(2) or '').lower())
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)


def open_zipfile(name):
    return get_zipfile(name)


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as z:
        return sum(n.lower().endswith('.jpg') for n in z.namelist())


class Uploader:
    def upload(self, itemname, filepaths):
        return run(['ia', 'upload', itemname, *filepaths, '--retries', '10'],
                   capture_output=True, text=True, check=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = run(['ia', 'list', item], capture_output=True, text=True, check=True)
        found = zip_filename in (line.strip().split('/')[-1] for line in result.stdout.splitlines())
        if verbose:
            print(item, zip_filename, 'uploaded' if found else 'missing')
        return found


class CoverDB:
    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return (int(start_id) // 10_000 + 1) * 10_000 - 1

    @staticmethod
    def update_completed_batch(item_id, batch_id, ext='jpg'):
        item_id, batch_id = Batch(item_id, batch_id)._norm_ids()
        start_id = int(item_id) * 1_000_000 + int(batch_id) * 10_000
        end_id = CoverDB._get_batch_end_id(start_id)
        database = db.getdb()
        transaction = database.transaction()
        try:
            for row in database.select('cover', where='id >= "'$start_id AND id <= $end_id '"'
                                       'AND archived = true AND failed = false',
                                       vars=locals()):
                fields = {f'filename_{size}' if size else 'filename':
                          Cover.get_cover_url(row.id, size, ext) for size in SIZES}
                database.update('cover', where='id="'$id AND archived=true AND failed=false'"',
                                vars={'id': row.id}, uploaded=True, **fields)
        except Exception:
            transaction.rollback()
            raise
        else:
            transaction.commit()


